from fractions import Fraction

def stop_when_up_exact(max_steps):
    """A fair walk from 0 stops at +1 or after max_steps steps.
    Return (chance it reached +1, E[S_T]) as exact Fractions."""
    dist = {0: Fraction(1)}      # positions still running, with their chances
    reached = Fraction(0)
    for _ in range(max_steps):
        new = {}
        for s, pr in dist.items():
            for t in (s + 1, s - 1):
                if t == 1:
                    reached += pr / 2
                else:
                    new[t] = new.get(t, 0) + pr / 2
        dist = new
    mean = reached * 1 + sum(s * pr for s, pr in dist.items())
    return reached, mean
